from sage.all_cmdline import *   # import sage library

_sage_const_2 = Integer(2); _sage_const_18 = Integer(18); _sage_const_3 = Integer(3); _sage_const_13 = Integer(13); _sage_const_1 = Integer(1); _sage_const_0 = Integer(0); _sage_const_5 = Integer(5); _sage_const_7 = Integer(7)# CryptoHack - Road to SIDH - Two Isogenies
# Compute the 2-isogeny phi_2 : E -> E' with kernel <K> and print j(E').

p = _sage_const_2 **_sage_const_18  * _sage_const_3 **_sage_const_13  - _sage_const_1 
